import { createElement, ensureElement } from "../utils/utils";
import { Modal } from "./base/Modal";
export class BasketModal extends Modal {
    constructor(elementsBlock, events, name) {
        super(events, elementsBlock);
        this.name = name;
    }
    addEventListeners() {
        super.addEventListeners();
        const basketButton = ensureElement('.button', this.element);
        basketButton.addEventListener('click', () => {
            this.events.emit('delivery:open');
        });
    }
    addRemoveListeners(btn, product) {
        btn.addEventListener('click', () => {
            this.events.emit('basket:delete', product);
        });
    }
    render(products, orderAmount) {
        const basketElement = ensureElement('.basket', this.element);
        const listElement = ensureElement('.basket__list', basketElement);
        const actionsElement = ensureElement('.modal__actions', basketElement);
        const priceElement = ensureElement('.basket__price');
        listElement.innerHTML = '';
        if (products.length !== 0) {
            products.forEach((product, index) => {
                const deleteButton = createElement('button', { className: 'basket__item-delete', ariaLabel: 'удалить' });
                const basketItem = createElement('li', { className: 'basket__item card card_compact' }, [
                    createElement('span', { className: 'basket__item-index', textContent: String(index + 1) }),
                    createElement('span', { className: 'card__title', textContent: product.title }),
                    createElement('span', { className: 'card__price', textContent: `${product.price} синапсов` }),
                    deleteButton
                ]);
                this.addRemoveListeners(deleteButton, product);
                listElement.append(basketItem);
            });
            actionsElement.style.display = 'flex';
            priceElement.textContent = `${orderAmount} синапсов`;
        }
        else {
            actionsElement.style.display = 'none';
            const emptyElement = createElement('div', { className: 'card__title basket__empty', textContent: 'Корзина пока пуста' });
            listElement.append(emptyElement);
        }
        this.open();
    }
}
