export class GlobalStore {
    constructor() {
        this.products = [];
        this.basketProducts = [];
    }
    setProducts(products) {
        this.products = products;
    }
    getBasketProducts() {
        return this.basketProducts;
    }
    addBasketProducts(product) {
        this.basketProducts.push(product);
    }
    deleteBasketProducts(product) {
        this.basketProducts = this.basketProducts.filter(item => {
            return item !== product;
        });
    }
    cleaningBasketProducts() {
        this.basketProducts.length = 0;
    }
    isProductInBasket(product) {
        return this.basketProducts.includes(product);
    }
    orderAmount() {
        let amount = 0;
        this.basketProducts.forEach(item => {
            if (item.price) {
                amount += item.price;
            }
        });
        return amount;
    }
    orderCount() {
        return this.basketProducts.length;
    }
    allProductsID() {
        const arrID = [];
        this.basketProducts.forEach((item) => {
            arrID.push(item.id);
        });
        return arrID;
    }
    setDelivery(delivery) {
        this.delivery = delivery;
    }
    getDelivery() {
        return this.delivery;
    }
    setContact(contact) {
        this.contact = contact;
    }
    getContact() {
        return this.contact;
    }
    getOrder() {
        return this.order = {
            payment: this.delivery.payment,
            email: this.contact.email,
            phone: this.contact.phone,
            address: this.delivery.address,
            total: this.orderAmount(),
            items: this.allProductsID()
        };
    }
}
