import { ensureElement } from "../utils/utils";
import { Modal } from "./base/Modal";
export class ResultModal extends Modal {
    constructor(elementsBlock, events, name) {
        super(events, elementsBlock);
        this.name = name;
    }
    addEventListeners() {
        super.addEventListeners();
        const buttonElement = ensureElement('.button', this.element);
        buttonElement.addEventListener('click', () => {
            this.events.emit('result:close');
        });
    }
    render(orderAmount) {
        const descriptionElement = ensureElement('.film__description', this.element);
        descriptionElement.textContent = `Списано ${orderAmount} синапсов`;
        this.open();
    }
}
